<script>
(()=>{'use strict';const base=<?= json_encode(site_url('cartella-clinica/demo-pacs/immagini').'/',JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?>;const img=document.getElementById('demoImage'),slice=document.getElementById('slice'),status=document.getElementById('imageStatus');let image=1,step=0;
function showImage(n){image=Math.max(1,Math.min(16,n));slice.value=image;document.getElementById('imageNumber').textContent=image;img.alt='Immagine '+image+' della serie DICOM sintetica';status.textContent='Caricamento immagine dal PACS…';img.src=base+image;document.getElementById('downloadDicom').href=base+image+'?download=1';}
img.onload=()=>status.textContent='Immagine '+image+'/16 verificata e pronta';img.onerror=()=>status.textContent='Immagine non disponibile: controllare il collegamento PACS e riprovare.';if(img.complete&&img.naturalWidth)status.textContent='Immagine 1/16 verificata e pronta';slice.onchange=()=>showImage(Number(slice.value));document.getElementById('previousImage').onclick=()=>showImage(image-1);document.getElementById('nextImage').onclick=()=>showImage(image+1);const zoom=document.getElementById('zoom'),contrast=document.getElementById('contrast');zoom.oninput=()=>img.style.transform='scale('+Number(zoom.value)/100+')';contrast.oninput=()=>img.style.filter='contrast('+contrast.value+'%)';document.getElementById('resetImage').onclick=()=>{zoom.value=contrast.value=100;img.style.transform='';img.style.filter='';};
const stages=[['Richiesta esame','Il medico seleziona il paziente e la prestazione, controlla i dati e conferma la richiesta. Si generano gli identificativi che permettono di collegare l’esame alle immagini.'],['Accettazione','La segreteria o il master registrano l’arrivo del paziente nella lista diagnostica.'],['Esecuzione','Il professionista registra l’inizio e la conclusione dell’esame. Le apparecchiature archiviano le immagini nel PACS secondo il collegamento concordato.'],['Consultazione immagini','Il gestionale verifica gli identificativi dell’esame e apre le immagini. Prova a scorrere la serie, cambiare zoom e scaricare un DICOM originale.'],['Referto','Il medico redige il referto collegato all’esame. Nella cartella operativa il documento può essere finalizzato in PDF e seguire il percorso di firma configurato. Qui puoi modificare una bozza dimostrativa.']];function render(){const box=document.getElementById('stage');box.replaceChildren();const h=document.createElement('h2'),p=document.createElement('p');h.textContent=stages[step][0];p.textContent=stages[step][1];box.append(h,p);document.querySelectorAll('[data-step]').forEach(b=>b.setAttribute('aria-current',String(Number(b.dataset.step)===step)));document.getElementById('reportEditor').hidden=step!==4;document.getElementById('nextStep').disabled=step===4;}document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{step=Number(b.dataset.step);render();});document.getElementById('nextStep').onclick=()=>{step=Math.min(4,step+1);render();};document.getElementById('restartDemo').onclick=()=>{step=0;render();showImage(1);};document.getElementById('downloadReport').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['DEMO - SENZA VALORE CLINICO\n\n'+document.getElementById('demoReport').value],{type:'text/plain;charset=utf-8'}));a.download='bozza-referto-dimostrativo.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);};render();})();
</script></body></html>
